24	// (de-duplicated, first occurrence wins, list order preserved) while keeping its
25	// existing direct downstreams. Reverse edges stay consistent: upstreams removed
26	// from the list drop the dataset from their children, newly added upstreams gain
27	// it at the end of their children, and retained upstreams keep exactly one entry
28	// in its original position.
29	//
30	// The whole request is validated before the graph is touched, so a rejected
31	// registration leaves every node, edge and ordering untouched. The parents slice
32	// is copied: mutating it after Register returns does not affect the graph.
33	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
34		if dataset.Name == "" {
35			return errInvalid("dataset name is required")
36		}
37	
38		// Validate up front, walking the request in input order so the first problem
39		// encountered is the one reported. No graph mutation happens in this loop.
40		upstreams := make([]string, 0, len(parents))
41		known := map[string]bool{}
42		for _, parent := range parents {
43			if parent == dataset.Name {
44				return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
45			}
46			if _, ok := graph[parent]; !ok {
47				return errInvalid("unknown parent " + parent)
48			}
49			// A new edge dataset -> parent closes a cycle exactly when parent can
50			// already reach dataset through existing parent edges. This covers
51			// transitive paths of any depth, not only direct mutual references.
52			if reaches(graph, parent, dataset.Name) {
53				return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
54			}
55			if !known[parent] {
56				known[parent] = true
57				upstreams = append(upstreams, parent)
58			}
59		}
60	
61		entry, existed := graph[dataset.Name]
62		if !existed {
63			entry = &Lineage{Dataset: dataset.Name}
64		}
65	
66		// Remove reverse edges from upstreams the dataset no longer declares.
67		for _, old := range entry.Parents {
68			if known[old] {
69				continue
70			}
71			if p, ok := graph[old]; ok {
72				p.Children = removeChild(p.Children, dataset.Name)
73			}
74		}
75	
76		// Mirror every declared upstream exactly once. An existing edge keeps its
77		// position; a missing edge is appended after the current children.
78		for _, parent := range upstreams {
79			graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
80		}
81	
82		entry.Parents = upstreams
83		if !existed {
84			graph[dataset.Name] = entry
85		}
