160	// Impacts returns every dataset directly or indirectly downstream of origin,
161	// i.e. every dataset reachable from origin by following child edges. The origin
162	// itself is never listed, and datasets with no such connection never appear.
163	//
164	// Distance is the shortest edge count; each dataset is returned at most once
165	// even where several branches merge into it. When several shortest paths exist,
166	// the lexicographically smallest full path (name by name, Go string order) is
167	// reported. Results are ordered by distance and then by dataset name, never by
168	// registration order or the stored parent/child list order.
169	//
170	// The graph is read only: a successful or failed query changes no node, edge or
171	// ordering. The returned Path slices are independent copies, so mutating them
172	// cannot affect the graph. An empty origin is rejected as a missing name; an
173	// origin absent from the graph (including an empty or nil graph) is rejected
174	// with an error naming it and no partial results.
175	func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
176		if origin == "" {
177			return nil, errInvalid("dataset name is required")
178		}
179		if _, ok := graph[origin]; !ok {
180			return nil, errInvalid("dataset not found: " + origin)
181		}
182	
183		// BFS one distance level at a time. A node commits its distance and best
184		// (lexicographically smallest) shortest path only once the whole level is
185		// known, so candidates reaching the same child through different parents in
186		// the same level can be compared before either wins. Register rejects
187		// cycles, so a committed node is never reached again at an equal level.
188		distance := map[string]int{origin: 0}
189		best := map[string][]string{origin: {origin}}
190		frontier := []string{origin}
191		for d := 0; len(frontier) > 0; d++ {
192			nextDistance := d + 1
193			candidates := map[string][]string{}
194			var next []string
195			for _, node := range frontier {
196				for _, child := range graph[node].Children {
197					if _, seen := distance[child]; seen {
198						continue // reached on an earlier, strictly shorter level
199					}
200					// Fresh backing array per candidate: paths must not alias each
201					// other or any slice stored in the graph.
202					candidate := make([]string, len(best[node])+1)
203					copy(candidate, best[node])
204					candidate[len(candidate)-1] = child
205					if current, ok := candidates[child]; !ok || lessPath(candidate, current) {
206						if !ok {
207							next = append(next, child)
208						}
209						candidates[child] = candidate
210					}
211				}
212			}
213			for _, child := range next {
214				distance[child] = nextDistance
215				best[child] = candidates[child]
216			}
217			frontier = next
218		}
219	
220		impacts := make([]Impact, 0, len(distance)-1)
221		for name, d := range distance {
222			if name == origin {
223				continue
224			}
225			impacts = append(impacts, Impact{
226				Dataset:  name,
227				Distance: d,
228				Path:     append([]string(nil), best[name]...),
229			})
230		}
231		sort.Slice(impacts, func(i, j int) bool {
232			if impacts[i].Distance != impacts[j].Distance {
233				return impacts[i].Distance < impacts[j].Distance
234			}
235			return impacts[i].Dataset < impacts[j].Dataset
236		})
237		return impacts, nil
238	}
239	
